import 'package:cloud_firestore/cloud_firestore.dart';
class AurenRandomMatch {final String id,uid,displayName,language,interest,goal,status;const AurenRandomMatch({required this.id,required this.uid,required this.displayName,required this.language,required this.interest,required this.goal,required this.status});factory AurenRandomMatch.fromDoc(DocumentSnapshot<Map<String,dynamic>> d){final m=d.data()??{};return AurenRandomMatch(id:d.id,uid:m['uid'] as String? ?? '',displayName:m['displayName'] as String? ?? 'AUREN User',language:m['language'] as String? ?? '',interest:m['interest'] as String? ?? '',goal:m['goal'] as String? ?? '',status:m['status'] as String? ?? 'waiting');}}
class AurenRandomConnectService{final FirebaseFirestore _db;AurenRandomConnectService({FirebaseFirestore? firestore}):_db=firestore??FirebaseFirestore.instance;CollectionReference<Map<String,dynamic>> get _c=>_db.collection('random_connect');
Future<String> join({required String uid,required String displayName,required String language,required String interest,required String goal})async{final ref=_c.doc();await ref.set({'uid':uid,'displayName':displayName.trim(),'language':language.trim(),'interest':interest.trim(),'goal':goal.trim(),'status':'waiting','createdAt':FieldValue.serverTimestamp()});return ref.id;}
Stream<List<AurenRandomMatch>> watchWaiting({String language='',String interest=''})=>_c.where('status',isEqualTo:'waiting').limit(50).snapshots().map((s)=>s.docs.map(AurenRandomMatch.fromDoc).where((x)=>language.trim().isEmpty||x.language.toLowerCase()==language.trim().toLowerCase()).where((x)=>interest.trim().isEmpty||x.interest.toLowerCase().contains(interest.trim().toLowerCase())).toList());
Future<void> cancel(String uid,String id)=>_c.doc(id).update({'status':'cancelled'});Future<void> connect(String myUid,String id)async{final r=_c.doc(id);final s=await r.get();if(!s.exists||s.data()?['uid']==myUid)return;await r.update({'status':'matched','matchedWith':myUid,'matchedAt':FieldValue.serverTimestamp()});}}
